import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Protocolo URI (lertaro://)","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/uri-protocol.md","filePath":"es-ES/user-guide/uri-protocol.md","lastUpdated":1787586465000}'),n={name:"es-ES/user-guide/uri-protocol.md"};function o(r,e,c,l,d,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="protocolo-uri-lertaro" tabindex="-1">Protocolo URI (lertaro://) <a class="header-anchor" href="#protocolo-uri-lertaro" aria-label="Permalink to &quot;Protocolo URI (lertaro://)&quot;">​</a></h1><p>En su primera ejecución, Lertaro registra automáticamente el protocolo personalizado <strong><code>lertaro://</code></strong> en Windows. Enlaces web, accesos directos de escritorio, scripts de automatización y herramientas de terceros pueden utilizar este protocolo para invocar búsquedas, acceder a secciones de configuración o iniciar transferencias inalámbricas.</p><h2 id="_1-funcionamiento-y-enrutamiento-a-instancia-unica" tabindex="-1">1. Funcionamiento y enrutamiento a instancia única <a class="header-anchor" href="#_1-funcionamiento-y-enrutamiento-a-instancia-unica" aria-label="Permalink to &quot;1. Funcionamiento y enrutamiento a instancia única&quot;">​</a></h2><ul><li><strong>Listo para usar</strong>: No requiere configuración manual en el registro de Windows; Lertaro comprueba y mantiene su registro al iniciarse.</li><li><strong>Enrutamiento a instancia única</strong>: Si Lertaro ya se está ejecutando en segundo plano, abrir un enlace <code>lertaro://</code> redirige la orden a la instancia activa en primer plano sin duplicar procesos. Si no está ejecutándose, Windows inicia la aplicación y ejecuta la acción solicitada.</li></ul><h2 id="_2-tabla-de-comandos-uri-admitidos" tabindex="-1">2. Tabla de comandos URI admitidos <a class="header-anchor" href="#_2-tabla-de-comandos-uri-admitidos" aria-label="Permalink to &quot;2. Tabla de comandos URI admitidos&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Formato de comando URI</th><th style="text-align:left;">Descripción y resultado visual</th></tr></thead><tbody><tr><td style="text-align:left;"><code>lertaro://</code></td><td style="text-align:left;">Activa y muestra la Ventana rápida (equivalente a doble pulsación de <code>Ctrl</code>).</td></tr><tr><td style="text-align:left;"><code>lertaro://search/[palabra_clave]</code></td><td style="text-align:left;">Abre la Ventana rápida con la <code>[palabra_clave]</code> precargada y filtrada.</td></tr><tr><td style="text-align:left;"><code>lertaro://fullsearch/[palabra_clave]</code></td><td style="text-align:left;">Abre la Ventana principal con la <code>[palabra_clave]</code> precargada.</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/page/[sección]</code></td><td style="text-align:left;">Abre Configuración y cambia directamente a la pestaña de nivel superior indicada.</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/entry/[id]</code></td><td style="text-align:left;">Abre Configuración y salta a una opción específica resaltándola.</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend</code></td><td style="text-align:left;">Abre la ventana vacía de transferencia inalámbrica de LocalSend.</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/items/[ruta_codificada...]</code></td><td style="text-align:left;">Abre LocalSend en modo archivo con una o varias rutas precargadas.</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/text/[texto_codificado]</code></td><td style="text-align:left;">Abre LocalSend en modo texto con el contenido listo para enviar.</td></tr></tbody></table><h3 id="secciones-de-configuracion-seccion" tabindex="-1">Secciones de configuración <code>[sección]</code> <a class="header-anchor" href="#secciones-de-configuracion-seccion" aria-label="Permalink to &quot;Secciones de configuración \`[sección]\`&quot;">​</a></h3><p>Los nombres de sección no distinguen mayúsculas y coinciden con la barra lateral de Configuración:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service      - Estado del servicio</span></span>
<span class="line"><span>Index        - Configuración de indexación</span></span>
<span class="line"><span>General      - Configuración general</span></span>
<span class="line"><span>Appearance   - Apariencia y temas</span></span>
<span class="line"><span>Hotkeys      - Atajos de teclado</span></span>
<span class="line"><span>Plugins      - Gestión de plugins</span></span>
<span class="line"><span>Favorites    - Favoritos</span></span>
<span class="line"><span>History      - Historial de búsqueda</span></span>
<span class="line"><span>QuickPanel   - Panel rápido</span></span>
<span class="line"><span>About        - Acerca de y actualizaciones</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>El número en <code>lertaro://settings/entry/[id]</code> se genera dinámicamente mediante el plugin interno de <a href="./instant-answers.html#2-extensiones-activadas-por-palabra-clave-plugins-integrados"><strong>Búsqueda en Configuración</strong></a>. Dado que los identificadores pueden variar entre versiones, se recomienda usar <code>lertaro://settings/page/[sección]</code> en scripts y enlaces externos.</p></div><h2 id="_3-parametros-de-localsend-y-codificacion" tabindex="-1">3. Parámetros de LocalSend y codificación <a class="header-anchor" href="#_3-parametros-de-localsend-y-codificacion" aria-label="Permalink to &quot;3. Parámetros de LocalSend y codificación&quot;">​</a></h2><p>Al invocar LocalSend mediante URI, cada ruta de archivo o fragmento de texto debe codificarse en formato URL estándar (p. ej. <code>:</code> como <code>%3A</code>, <code>\\</code> como <code>%5C</code> y espacios como <code>%20</code>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Precargar varias rutas de archivo</span></span>
<span class="line"><span>lertaro://localsend/items/C%3A%5CUsers%5Ctestuser%5CDesktop%5Cdoc.pdf/D%3A%5CShared%5Cphotos</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Precargar texto para enviar</span></span>
<span class="line"><span>lertaro://localsend/text/Hello%20from%20Lertaro%21</span></span></code></pre></div><ul><li><strong>Requisitos de seguridad</strong>: Todas las rutas deben corresponder a rutas absolutas existentes en el equipo local. Los enlaces con datos precargados únicamente abren la selección de dispositivos; nunca inician la transferencia de forma automática.</li></ul><h2 id="_4-ejemplos-de-integracion-externa" tabindex="-1">4. Ejemplos de integración externa <a class="header-anchor" href="#_4-ejemplos-de-integracion-externa" aria-label="Permalink to &quot;4. Ejemplos de integración externa&quot;">​</a></h2><h3 id="enlaces-en-markdown-y-bases-de-conocimiento" tabindex="-1">Enlaces en Markdown y bases de conocimiento <a class="header-anchor" href="#enlaces-en-markdown-y-bases-de-conocimiento" aria-label="Permalink to &quot;Enlaces en Markdown y bases de conocimiento&quot;">​</a></h3><p>Inserta enlaces directos en Obsidian, Notion o documentos Markdown:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Abrir [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Configuración de apariencia de Lertaro</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://settings/page/Appearance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Buscar [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Estados financieros</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://search/informe%20financiero%202026</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="accesos-directos-y-scripts-de-windows" tabindex="-1">Accesos directos y scripts de Windows <a class="header-anchor" href="#accesos-directos-y-scripts-de-windows" aria-label="Permalink to &quot;Accesos directos y scripts de Windows&quot;">​</a></h3><p>Crea un acceso directo en el escritorio y escribe en la ubicación del destino:</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lertaro://fullsearch/D:\\Projects\\</span></span></code></pre></div><p>Invocación desde PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Process</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;lertaro://settings/page/General&quot;</span></span></code></pre></div><h2 id="_5-seguridad-y-tolerancia-ante-rutas-desconocidas" tabindex="-1">5. Seguridad y tolerancia ante rutas desconocidas <a class="header-anchor" href="#_5-seguridad-y-tolerancia-ante-rutas-desconocidas" aria-label="Permalink to &quot;5. Seguridad y tolerancia ante rutas desconocidas&quot;">​</a></h2><ul><li><strong>Gestión segura y silenciosa</strong>: Dado que cualquier página web o aplicación puede invocar el protocolo, Lertaro valida de forma estricta todas las solicitudes URI. Las rutas con formato incorrecto o inexistentes se ignoran de forma segura y se registran en los registros de depuración sin generar fallos ni comportamientos inesperados.</li></ul>`,25)])])}const g=a(n,[["render",o]]);export{h as __pageData,g as default};
